const out = [];
const IPV4 = /\b(?:(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\b/g;
const HASH = /\b[a-fA-F0-9]{64}\b|\b[a-fA-F0-9]{40}\b|\b[a-fA-F0-9]{32}\b/g;
const DOMAIN = /\b(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}\b/g;
const PRIVATE = /^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|127\.)/;
function firstPublicIp(list){ for (const ip of list){ if(ip && !PRIVATE.test(ip)) return ip; } return list[0] || ""; }
function categorize(text){
  const t = (text || "").toLowerCase();
  if (/phish|spoof|business email|bec/.test(t)) return "phishing";
  if (/brute|multiple auth|failed password|password spray|login fail/.test(t)) return "brute_force";
  if (/malware|trojan|ransomware|virus|payload|c2|command and control|beacon/.test(t)) return "malware";
  if (/exfil|data loss|dlp/.test(t)) return "exfiltration";
  if (/priv esc|privilege escalation|sudo|uac/.test(t)) return "privilege_escalation";
  if (/scan|recon|port sweep|enumeration/.test(t)) return "recon";
  return "other";
}
const MITRE_BY_CAT = { phishing:"T1566", brute_force:"T1110", malware:"T1204", exfiltration:"T1041", privilege_escalation:"T1068", recon:"T1595", other:"T1059" };
for (const item of $input.all()) {
  const raw = item.json && item.json.body ? item.json.body : item.json;
  const b = raw || {};
  let source = (b.source || "").toLowerCase();
  if (!source) {
    if (b.rule && b.agent) source = "wazuh";
    else if (b.event_type || (b.alert && b.alert.signature)) source = "suricata";
    else if (b.properties && b.properties.alertDisplayName) source = "sentinel";
    else if (b.result || b._raw) source = "splunk";
    else source = "unknown";
  }
  let rule_name = "", severity = "medium", srcuser = "", hostname = "", event_time = b.timestamp || new Date().toISOString();
  let mitre = "";
  const blob = JSON.stringify(b);
  if (source === "wazuh") {
    rule_name = (b.rule && b.rule.description) || "Wazuh alert";
    const lvl = (b.rule && b.rule.level) || 5;
    severity = lvl >= 12 ? "critical" : lvl >= 9 ? "high" : lvl >= 6 ? "medium" : "low";
    srcuser = (b.data && (b.data.srcuser || b.data.dstuser)) || "";
    hostname = (b.agent && b.agent.name) || "";
    mitre = (b.rule && b.rule.mitre && b.rule.mitre.id && b.rule.mitre.id[0]) || "";
  } else if (source === "suricata") {
    rule_name = (b.alert && b.alert.signature) || b.event_type || "Suricata event";
    severity = (b.alert && b.alert.severity === 1) ? "high" : "medium";
    hostname = b.host || "";
  } else if (source === "sentinel") {
    rule_name = (b.properties && b.properties.alertDisplayName) || "Sentinel alert";
    severity = ((b.properties && b.properties.severity) || "medium").toLowerCase();
    hostname = (b.properties && b.properties.compromisedEntity) || "";
  } else if (source === "splunk") {
    const r = b.result || b;
    rule_name = r.search_name || r.signature || "Splunk notable";
    severity = (r.severity || r.urgency || "medium").toLowerCase();
    srcuser = r.user || "";
    hostname = r.host || r.dest || "";
  } else {
    rule_name = b.rule_name || b.title || "Generic alert";
  }
  const ips = (blob.match(IPV4) || []);
  const hashes = (blob.match(HASH) || []);
  const domains = (blob.match(DOMAIN) || []).filter(d => !/\.(png|jpg|gif|json|log|exe|dll|txt)$/i.test(d));
  const explicitSrc = (b.data && b.data.srcip) || (b.src_ip) || "";
  const explicitDst = (b.data && b.data.dstip) || (b.dest_ip) || "";
  const src_ip = explicitSrc || firstPublicIp(ips) || "";
  const dest_ip = explicitDst || (ips.find(ip => ip !== src_ip) || "");
  const category = categorize(rule_name + " " + blob);
  if (!mitre) mitre = MITRE_BY_CAT[category] || "";
  const alert_id = (b.id || b.alert_id || (source + "-" + Date.now() + "-" + Math.floor(Math.random()*100000)));
  out.push({ json: {
    alert_id: String(alert_id), source, event_time, rule_name, severity,
    src_ip, dest_ip, file_hash: hashes[0] || "", domain: domains[0] || "",
    username: srcuser, hostname, alert_category: category, mitre_technique: mitre,
    ioc_ips: ips, ioc_hashes: hashes, ioc_domains: domains, raw_alert: b,
  }});
}
return out;

function safe(fn){ try { return fn(); } catch(e){ return undefined; } }
const norm = safe(() => $("Normalize Alert").first().json) || {};
const vt = safe(() => $("VirusTotal Lookup").first().json) || {};
const abuse = safe(() => $("AbuseIPDB Lookup").first().json) || {};
const shodan = safe(() => $("Shodan Lookup").first().json) || {};
const misp = safe(() => $("MISP Lookup").first().json) || {};
const octi = safe(() => $("OpenCTI Lookup").first().json) || {};

const vtMal = Number(safe(() => vt.data.attributes.last_analysis_stats.malicious)) || 0;
const vtSusp = Number(safe(() => vt.data.attributes.last_analysis_stats.suspicious)) || 0;
const abuseScore = Number(safe(() => abuse.data.abuseConfidenceScore)) || 0;
const abuseReports = Number(safe(() => abuse.data.totalReports)) || 0;
const shodanVulns = (safe(() => shodan.vulns) || []).length;
const mispHits = (safe(() => misp.response.Attribute) || []).length;
const octiEdges = (safe(() => octi.data.indicators.edges) || []);
const octiScore = octiEdges.length ? Math.max.apply(null, octiEdges.map(e => Number(safe(() => e.node.x_opencti_score)) || 0)) : 0;

const sevBase = { critical: 25, high: 18, medium: 10, low: 3 }[norm.severity] || 8;
let score = sevBase;
score += Math.min(vtMal * 6, 30);
score += Math.min(vtSusp * 2, 8);
score += Math.min(abuseScore * 0.25, 25);
score += Math.min(shodanVulns * 4, 12);
score += mispHits > 0 ? 18 : 0;
score += Math.min(octiScore * 0.18, 18);
score = Math.max(0, Math.min(Math.round(score), 100));

// Correlation: count independent intel sources that flagged the IOC
const sourcesHit = [vtMal > 0 || vtSusp > 0, abuseScore >= 25, shodanVulns > 0, mispHits > 0, octiScore >= 50].filter(Boolean).length;
const corroborated = sourcesHit >= 2;

let disposition, triage_tier;
if (score >= 70 || (mispHits > 0 && vtMal >= 3)) { disposition = "malicious"; triage_tier = "L2"; }
else if (score >= 40 || corroborated) { disposition = "suspicious"; triage_tier = "L1"; }
else { disposition = "benign"; triage_tier = "L1"; }

const enrichment = {
  virustotal: { malicious: vtMal, suspicious: vtSusp, reputation: safe(() => vt.data.attributes.reputation) },
  abuseipdb: { confidence: abuseScore, reports: abuseReports, country: safe(() => abuse.data.countryCode), tor: safe(() => abuse.data.isTor) },
  shodan: { vulns: safe(() => shodan.vulns) || [], ports: safe(() => shodan.ports) || [], org: safe(() => shodan.org) },
  misp: { hits: mispHits, events: (safe(() => misp.response.Attribute) || []).map(a => safe(() => a.Event.info)).filter(Boolean) },
  opencti: { score: octiScore, indicators: octiEdges.length },
  correlation: { sources_hit: sourcesHit, corroborated },
};

const urgency = score >= 85 ? 1 : score >= 60 ? 2 : 3;
const impact = norm.severity === "critical" ? 1 : norm.severity === "high" ? 2 : 3;

return [{ json: Object.assign({}, norm, {
  threat_score: score,
  disposition,
  triage_tier,
  correlation_sources: sourcesHit,
  servicenow_urgency: urgency,
  servicenow_impact: impact,
  enrichment,
  enrichment_json: JSON.stringify(enrichment),
  processed_at: new Date().toISOString(),
  summary: norm.rule_name + " | " + disposition.toUpperCase() + " | score " + score + "/100 | " + (norm.mitre_technique || "n/a") + " | src " + (norm.src_ip || "n/a"),
}) }];

